#!/usr/bin/env python3
"""Independently decode public address QRs generated by production qrcoded.c."""
import pathlib
import subprocess
import tempfile

from embit import bech32
from embit.script import Script
import zxingcpp

ROOT = pathlib.Path(__file__).resolve().parent
REPO = ROOT.parents[1]
BUILD = ROOT / 'build'
BUILD.mkdir(exist_ok=True)
HARNESS = BUILD / 'address-qr-harness'
subprocess.run([
    'cc', '-std=c99', '-O2', '-I' + str(REPO/'src'),
    str(REPO/'src/qrcoded.c'), str(ROOT/'harness.c'), '-o', str(HARNESS),
], check=True)

# Public zero-entropy BIP39 test seeds, first receiving path m/84'/0'/0'/0/0.
# The 12-word address is also the published BIP84 test vector.
vectors = [
    ('12-word-zero', 'bc1qcr8te4kr609gcawutmrza0j4xv80jy8z306fyu',
     '0014c0cebcd6c3d3ca8c75dc5ec62ebe55330ef910e2'),
    ('24-word-zero', 'bc1qzmtrqsfuaf6l6kkcsseumq26ukaphfj9skkug6',
     '001416d630413cea75fd5ad88433cd815ae5ba1ba645'),
]
checked = 0
with tempfile.TemporaryDirectory(prefix='address-qr-', dir=BUILD) as temporary:
    for name, address, script_hex in vectors:
        for scale in (3, 4):
            case = f'{name}-{scale}px'
            path = pathlib.Path(temporary) / f'{case}.pgm'
            metadata = subprocess.check_output([str(HARNESS), address, str(scale), str(path)], text=True)
            assert tuple(map(int, metadata.split())) == (2, 25, 0, 1), (case, 'expected version2/size25/ECC_LOW/alphanumeric')

            magic, dimensions, maximum, pixels = path.read_bytes().split(b'\n', 3)
            width, height = map(int, dimensions.split())
            assert magic == b'P5' and maximum == b'255'
            assert width == height == 33 * scale and len(pixels) == width * height
            image = memoryview(pixels).cast('B', shape=(height, width))
            barcode = zxingcpp.read_barcode(image, formats=zxingcpp.BarcodeFormat.QRCode, try_invert=False)
            assert barcode is not None and barcode.valid, (case, 'independent QR decode failed')
            decoded = barcode.bytes.decode('ascii')
            assert decoded == address.upper(), (case, 'QR payload changed')

            # Uppercase Bech32 represents the same witness program. SeedSigner
            # normalizes scanned Bech32 to lowercase before using embit's
            # higher-level Script.from_address(), which expects that prefix.
            expected_witness = bech32.decode('bc', address)
            assert expected_witness[0] == 0 and len(expected_witness[1]) == 20
            assert bech32.decode('bc', decoded) == expected_witness
            normalized = decoded.lower()
            assert normalized == address
            assert Script.from_address(normalized).data.hex() == script_hex
            assert Script.from_address(address).data.hex() == script_hex
            checked += 1

print(f'PASS: {checked} address QRs independently decoded at both display scales; uppercase payloads and unchanged scriptPubKeys verified.')
